package com.blooddonor.controller;
import com.blooddonor.repository.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/admin") public class AdminController { private final DonorRepository donors; private final BloodRequestRepository requests; private final UserAccountRepository users; public AdminController(DonorRepository d,BloodRequestRepository r,UserAccountRepository u){donors=d;requests=r;users=u;} @GetMapping("/dashboard") public String dashboard(Model m){m.addAttribute("donorCount",donors.count());m.addAttribute("requestCount",requests.count());m.addAttribute("userCount",users.count());m.addAttribute("donors",donors.findAll());return "admin/dashboard";} }
